    b_j &\sim \mathcal{N}(0, 1), \label{eq:prior_b} \\
    c_j &\sim \text{Beta}(5, 20), \label{eq:prior_c} \\
    d_j &\sim \text{Beta}(20, 5), \label{eq:prior_d} \\
    \gamma &\sim \mathcal{N}(0, 1). \label{eq:prior_gamma}
\end{align}
