\centering
\small
\begin{tabular}{lcccc}
\toprule
\textbf{Method} & \textbf{Detects} & \textbf{Calibrates} & \textbf{UQ} & \textbf{RL-robust} \\
\midrule
Min-K\%++ & \checkmark & & & \\
ConStat & \checkmark & & & \\
Self-Critique & \checkmark & & & \checkmark \\
KDS & \checkmark & & & ? \\
DCR & \checkmark & \checkmark & & \\
PSN-IRT & & & & \\
HiBayES & & & \checkmark & \\
\textbf{ContamCal} & \checkmark & \checkmark & \checkmark & \checkmark \\
